insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('ca1b454dc067', 'Sie hat recht, wobei einige Fragen offen bleiben.', '…, wobei …', 'She is right, though some questions remain open.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘wobei’ ist subordinierend: Verb am Nebensatzende.', 'Sie hat recht, {{wobei}} einige Fragen offen bleiben.', array['Sie','hat','recht,','wobei','einige','Fragen','offen','bleiben.']::text[], array['allerdings','jedoch','bleibt']::text[], array['konnektor','einschraenkung']::text[], 2) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('583a1e3d24e3', 'Das stimmt, jedenfalls im Großen und Ganzen.', '…, jedenfalls …', 'That''s true, at least by and large.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘jedenfalls’ schränkt die Geltung ein.', 'Das stimmt, {{jedenfalls}} im Großen und Ganzen.', array['Das','stimmt,','jedenfalls','im','Großen','und','Ganzen.']::text[], array['allerdings','freilich','stimmen']::text[], array['konnektor','einschraenkung']::text[], 2) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('12f5e957d977', 'Sofern es nicht regnet, gehen wir spazieren.', 'Sofern …, …', 'Provided it doesn''t rain, we''ll go for a walk.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘sofern’ ist subordinierend: Verb am Nebensatzende, dann Inversion.', '{{Sofern}} es nicht regnet, gehen wir spazieren.', array['Sofern','es','nicht','regnet,','gehen','wir','spazieren.']::text[], array['Wenn','Falls','gehst']::text[], array['konnektor','bedingung']::text[], 2) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('36ea5b4cbd0d', 'Beeil dich, andernfalls verpassen wir den Bus.', '…, andernfalls …', 'Hurry up, otherwise we''ll miss the bus.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘andernfalls’ löst Inversion aus.', 'Beeil dich, {{andernfalls}} verpassen wir den Bus.', array['Beeil','dich,','andernfalls','verpassen','wir','den','Bus.']::text[], array['sonst','ansonsten','verpasst']::text[], array['konnektor','bedingung']::text[], 2) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('5ebe61644961', 'Vorausgesetzt, du hilfst mir, schaffen wir es.', 'Vorausgesetzt, …, …', 'Provided you help me, we''ll manage it.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘vorausgesetzt(, dass)’ leitet eine Bedingung ein.', '{{Vorausgesetzt,}} du hilfst mir, schaffen wir es.', array['Vorausgesetzt,','du','hilfst','mir,','schaffen','wir','es.']::text[], array['Sofern','Falls','schafft']::text[], array['konnektor','bedingung']::text[], 3) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('0a7572c0133e', 'Wir kommen, falls das Wetter passt.', '…, falls …', 'We''ll come if the weather is right.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘falls’ ist subordinierend: Verb am Nebensatzende.', 'Wir kommen, {{falls}} das Wetter passt.', array['Wir','kommen,','falls','das','Wetter','passt.']::text[], array['wenn','sofern','passen']::text[], array['konnektor','bedingung']::text[], 1) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('d5633cb10d9c', 'Im Falle eines Defekts erstatten wir das Geld.', 'Im Falle … …', 'In the event of a defect, we will refund the money.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘im Falle’ + Genitiv; danach Inversion.', 'Im {{Falle}} eines Defekts erstatten wir das Geld.', array['Im','Falle','eines','Defekts','erstatten','wir','das','Geld.']::text[], array['Sofern','Falls','erstatten,']::text[], array['konnektor','bedingung']::text[], 3) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('43060d7ab1ec', 'Angenommen, es klappt, feiern wir groß.', 'Angenommen, …, …', 'Assuming it works out, we''ll celebrate big.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘angenommen(, dass)’ leitet eine hypothetische Bedingung ein.', '{{Angenommen,}} es klappt, feiern wir groß.', array['Angenommen,','es','klappt,','feiern','wir','groß.']::text[], array['Vorausgesetzt','Falls','feiert']::text[], array['konnektor','bedingung']::text[], 3) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
