insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('787e69428102', 'Sie blieb hart, dessen ungeachtet liebte er sie.', '…, dessen ungeachtet …', 'She stayed firm; regardless of that, he loved her.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘dessen ungeachtet’ löst Inversion aus (gehoben).', 'Sie blieb hart, dessen {{ungeachtet}} liebte er sie.', array['Sie','blieb','hart,','dessen','ungeachtet','liebte','er','sie.']::text[], array['trotzdem','dennoch','liebten']::text[], array['konnektor','einraeumung']::text[], 4) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
