insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('b98fe8c5d200', 'Man müsste abwägen, ob sich der Aufwand wirklich lohnt.', 'man müsste abwägen, ob …', 'One would have to weigh up whether the effort is really worth it.', 'C1', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'müsste + abwägen, ob …: distanziert-reflektierend.', 'Man müsste {{abwägen}}, ob sich der Aufwand wirklich lohnt.', array['Man','müsste','abwägen,','ob','sich','der','Aufwand','wirklich','lohnt.']::text[], array['muss','dass','abgewogen']::text[], array['abwaegen','konjunktiv']::text[], 3) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('4ef373021ec3', 'Bei aller Begeisterung sollten wir die Risiken nicht unterschätzen.', 'bei aller Begeisterung sollten wir …', 'For all our enthusiasm, we shouldn''t underestimate the risks.', 'C2', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'Gehobene Wendung ''bei aller …'' relativiert höflich.', 'Bei aller Begeisterung sollten wir die Risiken nicht {{unterschätzen}}.', array['Bei','aller','Begeisterung','sollten','wir','die','Risiken','nicht','unterschätzen.']::text[], array['allen','wird','überschätzen']::text[], array['abwaegen','formell']::text[], 4) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('3ba7838fa52f', 'So verlockend das klingt, praktikabel ist es kaum.', 'so … das klingt, … ist es kaum', 'As tempting as that sounds, it''s hardly practical.', 'C2', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'Konzessive ''so … das auch …''-Konstruktion, hier verkürzt.', 'So {{verlockend}} das klingt, praktikabel ist es kaum.', array['So','verlockend','das','klingt,','praktikabel','ist','es','kaum.']::text[], array['wie','sehr','klingen']::text[], array['abwaegen','konzessiv']::text[], 4) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
