insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('8f014feb3bf9', 'Dann halten wir als Kompromiss die Mitte fest.', 'dann halten wir … fest', 'Then let''s settle on the middle ground as a compromise.', 'C1', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', 'etwas festhalten (trennbar): ein Ergebnis festschreiben.', 'Dann halten wir als Kompromiss die Mitte {{fest}}.', array['Dann','halten','wir','als','Kompromiss','die','Mitte','fest.']::text[], array['festhalten','Kompromisse','auf']::text[], array['einigung','kompromiss']::text[], 3) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
