insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty) values ('7c458551b595', 'Damit komme ich zu einem zentralen Aspekt meines Themas.', 'damit komme ich zu einem Aspekt', 'This brings me to a central aspect of my topic.', 'C1', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'Verbindet Abschnitte und betont die Relevanz.', 'Damit {{komme}} ich zu einem zentralen Aspekt meines Themas.', array['Damit','komme','ich','zu','einem','zentralen','Aspekt','meines','Themas.']::text[], array['kommen','einen','zentrale']::text[], array['uebergang','formell']::text[], 3) on conflict (id) do update set phrase_de=excluded.phrase_de, translation_en=excluded.translation_en, tokens=excluded.tokens, distractors=excluded.distractors;
